import { 
  MeshBasicNodeMaterial, 
  PlaneGeometry,
  Mesh,
  Group
} from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: ThreePlaneGeometry } = ctx.THREE;

  // Create output group
  const group = new ThreeGroup();

  // Create cleanup registry
  const timelines = [];
  const resourcesToDispose = [];

  // Color Palette from Spec
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    surface: "#0b0b10"
  };

  // 1. Build Backdrop/Stage to avoid Flat Void
  // ~7x6 units at z=-2.5 carrying a vertical gradient.
  // Since we need to construct it with standard NodeMaterials, we can build a solid backdrop structure
  // with a dark surface color.
  const bgGeo = new ThreePlaneGeometry(8, 7);
  const bgMat = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.9,
    depthWrite: false
  });
  const bgMesh = new ThreeMesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);
  resourcesToDispose.push(bgGeo, bgMat);

  // 2. Main Sprite Setup (Atlas Region: 0, 0, 512, 320)
  // Aspect ratio: 512 / 320 = 1.6
  const width = 2.4;
  const height = width / 1.6;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0, // Animated in
    depthWrite: true
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);
  resourcesToDispose.push(geometry, material);

  // Apply texture if imageUrl is provided
  const imageUrl = config.imageUrl ?? (config.intent?.visualSpec?.imageUrl);
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      // Configure UV mapping for atlas region format if required.
      // Source rect indicates the sub-region if it's on an atlas, 
      // but standard loadTexture handles correct mapping.
      material.colorNode = texture;
      material.needsUpdate = true;
    }).catch((err) => {
      console.warn("Failed loading texture in Pricing Card 1:", err);
    });
  }

  // 3. Motion Weight (Entrance Animation)
  // GSAP rise-in / fade-up style entrance
  mesh.position.y = -0.3;
  const entranceTl = gsap.timeline();
  entranceTl.to(mesh.position, {
    y: 0,
    duration: 0.8,
    ease: "power3.out"
  });
  entranceTl.to(material, {
    opacity: 1,
    duration: 0.6,
    ease: "power2.out"
  }, 0);
  timelines.push(entranceTl);

  // Define UserData / Cleanup Lifecycle
  group.userData = {
    handlers: {},
    cleanup: () => {
      // Kill all active GSAP animations
      timelines.forEach(tl => tl.kill());

      // Dispose Geometries and Materials
      resourcesToDispose.forEach(res => {
        if (res && typeof res.dispose === 'function') {
          res.dispose();
        }
      });
    }
  };

  return group;
}
